from pathlib import Path
root=Path(__file__).parent
parent=root.parent
stats=['ma','md','ra','rd','fit','int','cha','per']
def inp(attr,label,value='',kind='text',extra=''):
 return f'<label>{label}<input type="{kind}" name="attr_{attr}" value="{value}" {extra}></label>'
def number(attr,label,value=0): return inp(attr,label,value,'number')
html='''<div class="solo-sheet"><input type="hidden" name="attr_roster_type" class="roster-type" value="crew"><header><div class="eyebrow">TECHNO-FANTASY ADVENTURE 2E · SOLO / CO-OP</div><h1><span class="crew-title">Crew dossier</span><span class="foes-title">Foe dossier</span></h1></header><div class="crew-bar">'''+inp('character_name','Roster name')+'''<label>Roster type<select name="attr_roster_type"><option value="crew">Crew</option><option value="foes">Foes</option></select></label><label>View<select name="attr_crew_view"><option value="roster">Full roster</option><option value="battle">Battle · active only</option></select></label>'''+number('round','Round',1)+'<div class="crew-only">'+number('heat','Heat')+'</div><div class="crew-only">'+number('shared_luck','Shared Luck')+'</div>'+'''</div><p class="hint">Choose Crew for your party or Foes for a separate opposition roster. Foes use target numbers and never roll. Existing entries are retained when switching. Add entries below. Mark participants Active, then switch to Battle view. Expand details only when needed. Loadout opens that entry’s weapon and trait lists. X-Factor is a reminder; apply its TN, damage and action effects manually.</p><h2>Roster</h2><fieldset class="repeating_members"><input type="hidden" name="attr_row_visible" class="row-visible" value="1"><div class="member-card"><input type="hidden" name="attr_display_profile" class="profile-state" value="party"><input type="hidden" name="attr_active" class="active-state" value="1"><div class="member-summary"><label class="check"><input type="checkbox" name="attr_active" value="1" checked>Active</label>'''+inp('member_name','Name')+'''<label class="member-profile">Profile<select name="attr_profile"><option value="">Sheet default</option><option value="party">Party</option><option value="foe">Foe</option></select></label>'''+number('health','HP',15)+number('health_max','Max',15)+inp('initiative','Chit')+'''<button type="action" name="act_loadout">Loadout</button></div><input type="checkbox" name="attr_expanded" class="expand-toggle" value="1" title="Expand combat and details"><span class="expand-label">Combat &amp; details</span><div class="quick-stats">'''
for stat in stats:
 html+=f'<label><span>{stat.upper()}</span><span class="party-stat"><button type="action" name="act_{stat}">Roll</button><input type="number" name="attr_{stat}" value="0" aria-label="{stat.upper()} bonus"></span><span class="foe-stat"><input type="number" name="attr_tn_{stat}" value="11" aria-label="{stat.upper()} target number"></span></label>'
html+='''</div><p class="foe-only hint">Foe: full target numbers, no rolls.</p><div class="member-combat">'''+number('move','Move',5)+'''<label class="party-only">Luck<input type="number" name="attr_luck" value="0" min="0"></label>'''+number('xfactor','X-Factor',0)+inp('conditions','Conditions')+'''</div><div class="member-details"><div class="detail-grid"><label>Role<select name="attr_role"><option>Fighter</option><option>Shooter</option><option>Champion</option><option>Specialist</option><option>Other</option></select></label>'''+inp('power','Type / power level','Standard')+number('armor_dice','Armor dice',0)+number('incoming_damage','Incoming damage bonus',2)+inp('armor_name','Armor / shield')+'''<div class="party-only"><button type="action" name="act_armor">Armor save</button></div><label class="party-only">Background<input type="text" name="attr_background"></label>'''+number('boons','Boons',0)+number('bumps','Bumps',0)+'''</div><label>Description / gear / campaign notes<textarea name="attr_notes"></textarea></label></div></div></fieldset><h2>Selected loadout: <span name="attr_selected_name">Choose Loadout on a roster entry</span></h2><input type="hidden" name="attr_selected_member"><input type="hidden" name="attr_selected_ready" class="selected-ready" value="0"><div class="loadout-editor"><p class="hint">Lists below belong to the selected roster entry. New entries are linked when you edit them. Use Add and Modify to add, delete or reorder. Selecting another member preserves existing lists.</p><h3>Weapons</h3><fieldset class="repeating_weapons"><input type="hidden" name="attr_owner"><input type="hidden" name="attr_row_visible" class="row-visible" value="1"><div class="loadout-card"><div class="weapon-grid">'''+inp('weapon_name','Weapon')+'''<label>Type<select name="attr_weapon_type"><option value="melee">Melee</option><option value="ranged">Ranged</option></select></label>'''+number('weapon_damage','Damage',2)+number('weapon_range','Range / reach',1)+'''<button type="action" name="act_attack">Attack</button></div><label>Properties<textarea name="attr_weapon_properties"></textarea></label></div></fieldset><h3>Traits & abilities</h3><fieldset class="repeating_traits"><input type="hidden" name="attr_owner"><input type="hidden" name="attr_row_visible" class="row-visible" value="1"><div class="loadout-card"><div class="trait-grid">'''+inp('trait_name','Trait / ability')+number('trait_uses','Uses',0)+'''</div><label>Effects / limitations<textarea name="attr_trait_notes"></textarea></label></div></fieldset></div><label>Roster notes<textarea name="attr_crew_notes"></textarea></label><footer>Unofficial TFA 2E sheet · Rules © Scott R. Pyle / Four-Color Studios</footer></div>'''
worker=(parent/'worker.js').read_text()
core=worker[:worker.index("on('sheet:opened")]
roll=worker[worker.index('function rollStat('):worker.index('STATS.forEach(')]
# Hide attack buttons for a Foe/inactive selected loadout as well as guarding workers.
solo=(root/'worker.js').read_text()
html=html.replace('<div class="loadout-editor">','<input type="hidden" name="attr_selected_can_roll" class="selected-can-roll" value="0"><div class="loadout-editor">')
template=(parent/'sheet.html').read_text().split('<rolltemplate',1)[1].split('</rolltemplate>',1)[0]
(root/'sheet.html').write_text(html+'\n<rolltemplate'+template+'</rolltemplate>\n<script type="text/worker">\n'+core+roll+solo+'\n</script>\n')
(root/'worker.bundle.js').write_text(core+roll+solo)
